#pragma once
#include "../modules/mx-delay-original/vendor/mxdelay_params.h"
using namespace JerzyAudio;
struct OriginalMXMapping {MXDelayParams p;
void setNormalized(unsigned id,double v){v=std::clamp(v,0.0,1.0);switch(id){case kMXMixId:p.mix=v;return;case kMXInputTrimId:p.inputTrim=v;return;case kMXOutputTrimId:p.outputTrim=v;return;case kMXRoutingId:p.routing=v;return;case kMXBypassId:p.bypass=v;return;case kMXSpillId:p.spill=v;return;case kMXMachineConditionId:p.machineCondition=v;return;default:break;}if(id>=kMXWetFx1TypeId&&id<=kMXWetFx4RouteId){unsigned q=id-kMXWetFx1TypeId;int fx=int(q/6),field=int(q%6);if(fx>=0&&fx<4){auto& z=p.fx[fx];switch(field){case kWetFxType:z.type=v;break;case kWetFxAmount:z.amount=v;break;case kWetFxRate:z.rate=v;break;case kWetFxDepth:z.depth=v;break;case kWetFxDrive:z.drive=v;break;case kWetFxRoute:z.route=v;break;}return;}}for(int s=0;s<2;++s){unsigned base=slotBase(s);if(id<base||id>=base+kMXSlotStride)continue;unsigned off=id-base;auto& x=p.slot[s];if(off<=kSlotDuck){switch(off){case kSlotAlgorithm:x.algorithm=v;break;case kSlotEnable:x.enable=v;break;case kSlotSync:x.sync=v;break;case kSlotDivision:x.division=v;break;case kSlotTime:x.time=v;break;case kSlotFeedback:x.feedback=v;break;case kSlotLevel:x.level=v;break;case kSlotPan:x.pan=v;break;case kSlotDuck:x.duck=v;break;default:break;}return;}if(off>=kSlotHeadPan1&&off<=kSlotHeadPan4){x.headPan[off-kSlotHeadPan1]=v;return;}if(off>=kSlotControlBase){unsigned q=off-kSlotControlBase;int a=(int)(q/kAlgoControls),c=(int)(q%kAlgoControls);if(a<kAlgorithmCount){x.c[a][c]=v;return;}}}}
};
